<script>(()=>{const tabs=document.getElementById('pmProjectTabs');if(!tabs)return;const groups={overview:[],budgets:Array.from(document.querySelectorAll('.phase-budget-section')),requests:[]};document.querySelectorAll('.main>section').forEach(s=>{if(s.classList.contains('phase-budget-section'))return;const h=s.querySelector('h3')?.textContent||'';(h.startsWith('Site Requests')||h.startsWith('Budget Version')||h.startsWith('Internal Budget Edit'))?groups.requests.push(s):groups.overview.push(s)});const show=n=>{Object.values(groups).flat().forEach(e=>e.hidden=true);groups[n].forEach(e=>e.hidden=false);tabs.querySelectorAll('button').forEach(b=>{b.classList.toggle('btn-primary',b.dataset.projectView===n);b.classList.toggle('btn-ghost',b.dataset.projectView!==n)});history.replaceState(null,'','#'+n)};tabs.addEventListener('click',e=>{const b=e.target.closest('[data-project-view]');if(b)show(b.dataset.projectView)});show(location.hash.slice(1)||'overview')})();</script>
